/* Task activity is shown first in one centered workspace. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),previous=detail;
detail=async function(id,...args){await previous(id,...args);const dialog=document.querySelector(shared?'#sharedDialog':'#details'),root=document.querySelector(shared?'#sharedDetail':'#detailBody');if(!dialog?.open||!root||!tasks.some(t=>t.id===id))return;document.body.classList.remove('task-drawer-open');const head=root.querySelector('.shared-task-head,.dialog-head');if(!head)return;root.querySelector('.task-focus-nav')?.remove();const sections=[...root.querySelectorAll('.shared-section,.task-section')],conversation=sections.find(s=>/گزارش و بازخورد|گفت‌وگو و بازخورد/.test(s.querySelector('h3')?.textContent||'')),files=sections.find(s=>/فایل/.test(s.querySelector('h3')?.textContent||''));const history=[...root.querySelectorAll('details')].find(d=>/همه سوابق|سوابق ارسال و تأیید/.test(d.querySelector('summary')?.textContent||''));const nav=document.createElement('div');nav.className='task-focus-nav';head.after(nav);if(conversation){conversation.querySelector('h3').textContent='سوابق و گفت‌وگوی کار';nav.after(conversation);if(history){history.open=true;conversation.after(history)}}const targets=[['سوابق و گفت‌وگو',conversation||history],['فایل‌ها و نسخه‌ها',files],['مسئول و مشخصات',root.querySelector('#taskAssignment')||root.querySelector('.task-facts,.shared-facts')]];for(const [title,target]of targets){if(!target)continue;const b=document.createElement('button');b.type='button';b.textContent=title;b.onclick=()=>{if(target.tagName==='DETAILS')target.open=true;target.scrollIntoView({behavior:'smooth',block:'start'})};nav.append(b)}dialog.scrollTop=0;if(args[0]===true&&files)files.scrollIntoView({block:'start'});
};
})();
